+    use super::*;
+
+    fn event(kind: &str, fields: &str) -> String {
+        format!("event: {kind}\ndata: {{\"type\":\"{kind}\"{fields}}}\n\n")
+    }
+
+    fn text_delta(delta: &str) -> String {
+        event(
