+        let payload = build_payload(&input);
+
+        assert_eq!(payload["input"], "hello");
+        assert_eq!(payload["max_output_tokens"], 128);
+        assert_eq!(payload["stream"], true);
+        assert_eq!(payload["store"], false);
+        assert_eq!(payload["ignore_eos"], true);
